"""Explain the actual lab's input contract before asking for its implementation."""
import re


def explain(lesson, language):
    task=lesson.get('challenge')
    if not task or language=='sql':return ''
    slug=lesson['id'].split('.')[-1]
    if slug=='basics':
        match=re.search(r'N × (\d+) \+ (\d+)', task['prompt'])
        if match:
            price,fee=match.groups()
            return f'N — количество товаров, {price} — цена одного, {fee} — фиксированная плата по условию модели. Сначала вычисли стоимость товаров N × {price}, затем прибавь {fee}. Даже при N = 0 формула даёт {fee}: так явно задана эта учебная модель. В ответе требуется только полученное число. Не заменяй N одним примером: программа должна прочитать его при каждом запуске.'
    return {
      'arrays':'Первое число N сообщает, сколько следующих чисел нужно обработать. Оно само не является элементом набора для поиска максимума. Начни с первого настоящего элемента, затем сравни остальные. Пример с одними отрицательными числами проверяет, не выбран ли ошибочно ноль в качестве начального максимума.',
      'search':'Нужно найти именно первое в исходном порядке число 7. Индекс считается с нуля. Сортировать данные нельзя: после сортировки изменятся исходные позиции. Если N = 0 или семёрки нет, результат -1. Это линейный поиск, а не требование применить все способы поиска из подробного раздела.',
      'strings':'Нужно считать отдельные знаки-цифры. В тексте a2b90 их три: 2, 9 и 0. Число 90 не считается одной цифрой. Нечисловые знаки пропускаются, пустая строка даёт 0. Задача ограничена ASCII, поэтому сейчас не требуется решать общий случай всех числовых знаков Unicode.',
      'nested':'Представь квадратную таблицу умножения от 1 до N. Для каждой пары номера строки i и столбца j прибавляется i × j. При N = 2 это 1, 2, 2 и 4, сумма 9. Один общий итог создаётся до обоих циклов. Вывести нужно итог, а не саму таблицу.',
      'booleans':'Ответом служит число 1 для подходящего значения и 0 для неподходящего. Слова true или false в этом формате не нужны. Проверь обе включённые границы — 10 и 20 — и соседние значения 9 и 21. Правило «внутри диапазона» требует одновременного выполнения нижней и верхней проверки.',
      'branches':'Три возможных ответа кодируют знак числа: -1 для отрицательного, 0 для самого нуля, 1 для положительного. Это не требование вывести исходное число. Для каждого запуска должен появиться один ответ. Пройди отдельно отрицательное, нулевое и положительное значение.',
      'testing':'Знак ! в обозначении N! здесь означает факториал, а не логическое отрицание языка. Это произведение всех целых от 1 до N. Например, 4! = 1 × 2 × 3 × 4 = 24. Для 0! по определению нужен 1, поэтому накопитель произведения начинают с 1, а не с 0.',
      'iteration':'Первое N задаёт длину набора, а не участвует в сумме. Среди следующих значений прибавляй только строго положительные. Ноль и отрицательные пропускаются. Если подходящих значений нет, ответ 0. Для суммы добавляется значение элемента; для количества добавлялась бы единица — это другая задача.',
    }.get(slug,'')
